<script>import {onMount} from 'svelte';import {linkTreesStore} from '../states/linkTreesStore.js';import * as api from '../api/linkTreeApi.js';import {router} from '../../../router.js';import {authStore} from '../../auth/states/authStore.js';import AddModal from '../modals/AddModal.svelte';import {getErrorMessage,formatDate} from '../../../helpers/toolsHelper.js';let query=$state('');let mineOnly=$state(false);let showAdd=$state(false);let busy=$state(false);let notice=$state('');let loadError=$state('');let items=$derived(linkTreesStore.items.filter(x=>(!mineOnly||String(x.user_id||x.user?.id||'')===String(authStore.user?.id||''))&&`${x.title||''} ${x.description||''}`.toLowerCase().includes(query.toLowerCase())));onMount(async()=>{try{await linkTreesStore.fetchAll();}catch(e){loadError=getErrorMessage(e);}});async function create(data){busy=true;try{await api.createLinkTree(data);showAdd=false;notice='Link Tree berhasil dibuat.';await linkTreesStore.fetchAll();}catch(e){notice=getErrorMessage(e);throw e;}finally{busy=false;}}async function remove(item){if(!confirm(`Hapus “${item.title}”? Tindakan ini tidak dapat dibatalkan.`))return;try{await api.deleteLinkTree(item.id);await linkTreesStore.fetchAll();notice='Link Tree berhasil dihapus.';}catch(e){notice=getErrorMessage(e);}}async function removeAll(){if(!items.length||!confirm('Hapus semua Link Tree? Tindakan ini tidak dapat dibatalkan.'))return;try{await api.deleteAllLinkTrees();await linkTreesStore.fetchAll();notice='Semua Link Tree berhasil dihapus.';}catch(e){notice=getErrorMessage(e);}}</script>
<svelte:head><title>Semua Link Tree · Delcom</title><meta name="description" content="Buat, cari, dan kelola koleksi tautanmu di Delcom Link Tree."/></svelte:head><div class="page-header"><div><p class="eyebrow">RUANG KERJA</p><h1>Semua Link Tree</h1><p class="muted">Kumpulkan, kelola, dan bagikan tautan pentingmu.</p></div><button class="btn btn-primary" onclick={()=>showAdd=true}><span aria-hidden="true">＋</span> Buat Link Tree</button></div>{#if notice}<div class="notice" role="status">{notice}<button aria-label="Tutup pemberitahuan" onclick={()=>notice=''}>×</button></div>{/if}<section class="stats-grid" aria-label="Statistik link tree"><article class="stat-card"><span class="stat-icon green">▦</span><div><p>Total koleksi</p><strong>{linkTreesStore.items.length}</strong></div></article><article class="stat-card"><span class="stat-icon blue">↗</span><div><p>Total tautan</p><strong>{linkTreesStore.totalLinks}</strong></div></article><article class="stat-card"><span class="stat-icon yellow">◎</span><div><p>Koleksi ditampilkan</p><strong>{items.length}</strong></div></article></section><section class="list-section"><div class="section-heading"><div><h2>Koleksi tautan</h2><p class="muted">Atur tautan berdasarkan kebutuhanmu.</p></div><button class="btn btn-light btn-small" onclick={removeAll} disabled={!items.length}>Hapus semua</button></div><div class="toolbar"><label class="search-box"><span aria-hidden="true">⌕</span><input aria-label="Cari link tree" placeholder="Cari nama atau deskripsi…" bind:value={query}/></label><label class="filter-check"><input type="checkbox" bind:checked={mineOnly}/> Milik saya</label></div>{#if linkTreesStore.loading}<div class="loading-state" role="status">Memuat koleksi tautan…</div>{:else if loadError}<div class="empty-state"><span>!</span><h3>Data belum dapat dimuat</h3><p>{loadError}</p><button class="btn btn-light" onclick={async()=>{loadError='';try{await linkTreesStore.fetchAll()}catch(e){loadError=getErrorMessage(e)}}}>Coba lagi</button></div>{:else if items.length===0}<div class="empty-state"><span>↗</span><h3>{query||mineOnly?'Belum ada link tree yang cocok.':'Belum ada Link Tree'}</h3><p>{query||mineOnly?'Coba kata kunci atau filter lain.':'Buat koleksi pertama untuk mulai mengatur tautanmu.'}</p>{#if !query&&!mineOnly}<button class="btn btn-primary" onclick={()=>showAdd=true}>Buat Link Tree pertama</button>{/if}</div>{:else}<div class="tree-grid">{#each items as item (item.id)}<article class="tree-card"><button class="tree-cover" aria-label={`Buka ${item.title}`} onclick={()=>router.navigate(`/link-trees/${item.id}`)}>{#if item.cover}<img src={item.cover} alt="" loading="lazy"/>{:else}<span class="cover-symbol">↗</span>{/if}<span class="privacy-badge">{item.type||'public'}</span></button><div class="tree-card-content"><button class="tree-title" onclick={()=>router.navigate(`/link-trees/${item.id}`)}>{item.title||'Tanpa judul'}</button><p class="tree-description">{item.description||'Belum ada deskripsi untuk koleksi ini.'}</p><div class="tree-meta"><span>↗ {item.total_links??item.items?.length??0} tautan</span><span>{formatDate(item.updated_at||item.created_at)}</span></div><div class="tree-card-actions"><button class="btn btn-light btn-small" onclick={()=>router.navigate(`/link-trees/${item.id}`)}>Kelola tautan</button><button class="icon-button danger-text" aria-label={`Hapus ${item.title}`} onclick={()=>remove(item)}>⌫</button></div></div></article>{/each}</div>{/if}</section>{#if showAdd}<AddModal onClose={()=>showAdd=false} onSave={create} {busy}/>{/if}
